const budgetTips = `<section id="budget" class="divider">${H.sectionLabel('The Money','$10,150–14,450 for four','A reconciled July 2026 planning band. Exact 2027 airfare, rooms, cars and operators must replace every proxy before booking.')} ${H.table(['Line item','Estimate · family of 4'],budgetRows)}<div class="twocol"><div class="listcard save-list"><h4>How the low case works</h4><ul><li>Stopover airfare at or below $3,600–4,000.</li><li>Reykjavík apartment plus family-rate Ischia/Cilento lodging.</li><li>Municipal geothermal pool, public beaches and shared boats.</li><li>Breakfasts and road lunches from groceries.</li></ul></div><div class="listcard splurge-list"><h4>What breaks the band</h4><ul><li>Separate one-way airfare instead of a stopover fare.</li><li>Two Reykjavík hotel rooms or premium Ischia resort pricing.</li><li>Private boats, beach clubs and restaurant-heavy days.</li><li>Late automatic-car inventory with one-way surcharge.</li></ul></div></div></section><section id="totals" class="divider">${H.sectionLabel('Bottom Line','Within the preferred maximum—conditionally','The $14,450 high case leaves only $550 below the preferred maximum.')} ${H.table(['Category','Estimate · family of 4'],totals,'budget-tbl grand')}<p class="rate-note">Booking gate: if complete air exceeds $4,800 or lodging exceeds $3,650, re-run the whole total before committing. The route is not honestly a $12k promise.</p></section><section id="tips" class="divider">${H.sectionLabel('Booking Order','Solve the route before the resorts','Refundable holds first; nonrefundable extras last.')}<div class="tips-order"><ol><li>Quote PIT→FCO with a three-night Iceland stopover<span> · first</span></li><li>Quote a protected FCO→PIT Jun 23 return<span> · same session</span></li><li>Hold Reykjavík, Forio, Castellabate and Fiumicino lodging<span> · refundable</span></li><li>Reserve the two automatic cars and inspect one-way terms<span> · before scarcity</span></li><li>Book Negombo, La Mortella and shared boats<span> · after rules/weather policies</span></li></ol></div><div class="tips-grid">${H.tipcard('Warm-water rule','Do not dilute the premise',[{flag:'Iceland ocean water does not count; use geothermal pools only.'}, 'Do not replace Cilento with the Algarve, Canaries or another cool-water coast.', 'Protect at least one full beach/boat fallback day in each Italian base.'])}${H.tipcard('Transfer rule','No heroic connections',[{flag:'Jun 14 must retain enough margin to miss one train and one hydrofoil.'}, 'Travel with ferry-ready bags; do not collect an Ischia rental car.', 'Keep the Jun 22 Fiumicino buffer even if a prettier final night tempts you.'])}</div></section>`;

